{
  "name": "@vasilvestre/opencode-hashline-edit",
  "version": "1.1.9",
  "description": "LINE#ID edit tool for OpenCode v2 - safe, hash-validated line-based file editing",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": "./dist/index.js"
  },
  "scripts": {
    "build": "tsc",
    "dev": "tsc --watch",
    "test": "vitest run",
    "lint": "eslint src --ext .ts"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "edit",
    "hashline",
    "line-edit"
  ],
  "author": "Valentin Silvestre",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/vasilvestre/opencode-hashline-edit"
  },
  "devDependencies": {
    "@types/node": "^22.0.0",
    "typescript": "^5.0.0",
    "vitest": "^5.0.5",
    "@opencode/plugin": "^2.2.3"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    }
  },
  "overrides": {
    "tslib": "2.8.1"
  }
}
